import { z } from "zod";
import { issueSignedToken } from "@vercel/blob";
import {
  handleUpload,
  handleUploadPresigned,
  type HandleUploadBody,
  type HandleUploadPresignedBody,
} from "@vercel/blob/client";
import { db } from "@/lib/db";
import { DELETION_DRAIN_MS } from "@/lib/account";
import { auth } from "@/auth";
import { validStoragePath, discardUnactivatedResume } from "@/lib/storage";
import { MAX_PDF_BYTES } from "@/lib/validation";
export async function POST(request: Request) {
  let cleanupFailed = false;
  try {
    const body = (await request.json()) as
      HandleUploadBody | HandleUploadPresignedBody;
    const authorize = async (pathname: string) => {
      const session = await auth();
      if (
        !session?.user.id ||
        request.headers.get("origin") !== new URL(request.url).origin ||
        !validStoragePath(session.user.id, pathname)
      )
        throw new Error("Unauthorized upload.");
      const user = await db.$transaction(async (tx) => {
        await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${session.user.id} FOR UPDATE`;
        return tx.user.findFirst({
          where: {
            id: session.user.id,
            deletionRequestedAt: null,
            isSuspended: false,
          },
          select: { id: true },
        });
      });
      if (!user) throw new Error("Account unavailable.");
      return user.id;
    };
    const onUploadCompleted = async ({
      blob,
      tokenPayload,
    }: {
      blob: { pathname: string };
      tokenPayload?: string | null;
    }) => {
      const { userId } = z
        .object({ userId: z.uuid() })
        .parse(JSON.parse(tokenPayload ?? "{}"));
      if (!validStoragePath(userId, blob.pathname))
        throw new Error("Invalid upload location.");
      try {
        await discardUnactivatedResume(
          userId,
          blob.pathname,
          new Date(Date.now() - DELETION_DRAIN_MS),
        );
      } catch {
        cleanupFailed = true;
        throw new Error("Upload cleanup requires retry.");
      }
    };
    const response =
      process.env.BLOB_STORE_ID && !process.env.BLOB_READ_WRITE_TOKEN
        ? await handleUploadPresigned({
            body: body as HandleUploadPresignedBody,
            request,
            getSignedToken: async (pathname) => {
              const userId = await authorize(pathname);
              const validUntil = Date.now() + 10 * 60000;
              return {
                token: await issueSignedToken({
                  pathname,
                  operations: ["put"],
                  validUntil,
                  allowedContentTypes: ["application/pdf"],
                  maximumSizeInBytes: MAX_PDF_BYTES,
                }),
                urlOptions: {
                  validUntil,
                  allowedContentTypes: ["application/pdf"],
                  maximumSizeInBytes: MAX_PDF_BYTES,
                  addRandomSuffix: false,
                  allowOverwrite: false,
                  tokenPayload: JSON.stringify({ userId }),
                },
              };
            },
            onUploadCompleted,
          })
        : await handleUpload({
            body: body as HandleUploadBody,
            request,
            onBeforeGenerateToken: async (pathname) => {
              const userId = await authorize(pathname);
              return {
                allowedContentTypes: ["application/pdf"],
                maximumSizeInBytes: MAX_PDF_BYTES,
                addRandomSuffix: false,
                allowOverwrite: false,
                tokenPayload: JSON.stringify({ userId }),
                validUntil: Date.now() + 10 * 60000,
              };
            },
            onUploadCompleted,
          });
    return Response.json(response);
  } catch {
    return Response.json(
      { error: "Secure upload failed. Sign in and try again." },
      { status: cleanupFailed ? 503 : 400 },
    );
  }
}
